import type { Metadata } from "next";
import { site } from "@/content/site";

/** Generated by src/app/og.png/route.tsx. */
export const OG_IMAGE = {
  url: "/og.png",
  width: 1200,
  height: 630,
  alt: `${site.name} — Senior SDET`,
} as const;

/**
 * Per-page metadata. Next.js merges `openGraph`/`twitter` shallowly, so each page
 * needs the full objects or it would inherit the home page's title and URL.
 */
export function pageMetadata({
  title,
  description,
  path,
  type = "website",
  publishedTime,
}: {
  title: string;
  description: string;
  /** Route path with trailing slash, e.g. `/about/`. */
  path: string;
  type?: "website" | "article";
  publishedTime?: string;
}): Metadata {
  const fullTitle = `${title} — ${site.name}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type,
      url: path,
      siteName: site.name,
      title: fullTitle,
      description,
      locale: "en_CA",
      images: [OG_IMAGE],
      ...(publishedTime ? { publishedTime } : {}),
    },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [OG_IMAGE.url] },
  };
}
